import { partition } from 'lodash-es';

import { getAggregatedNode } from './get-aggregated-node.js';
import { isBelowTreshold } from './is-below-treshold.js';
import { InternalTreeMapClusterNode } from '../types/internal.js';

/**
 * Calculates the aggregated data for a treemap based on the provided data and treemap area.
 * @param cluster - TreeMap data cluster node
 * @param areaPerValue - proportionate area of treemap per value
 * @param minNodeSize - node threshold in pixels
 * @returns - TreeMap data child node with aggregated nodes
 */

export const getAggregatedCluster = (
  cluster: InternalTreeMapClusterNode,
  areaPerValue: number,
  minNodeSize: number,
) => {
  if (cluster.children === undefined || cluster.children.length === 1) {
    return cluster;
  }

  const [nodesToAggreagate, remainingNodes] = partition(
    cluster.children,
    (node) => isBelowTreshold(node, areaPerValue, minNodeSize),
  );

  if (!nodesToAggreagate.length) {
    return cluster;
  }

  const aggregatedNode = getAggregatedNode(nodesToAggreagate, cluster.color);

  // if aggregatedNode is still below threshold, merge it to the smallest remainingNode
  if (isBelowTreshold(aggregatedNode, areaPerValue, minNodeSize)) {
    const smallestRemainingNode = remainingNodes.pop() ?? { value: 0 };
    aggregatedNode.value += smallestRemainingNode.value;
  }
  return { ...cluster, children: [...remainingNodes, aggregatedNode] };
};
